  const stamp = toIsoTimestamp(new Date());
  const rows = getDb()
    .insert(notifications)
    .values(
      inputs.map((input) => ({
        id: newId(),
        orgId,
        recipientId: input.recipientId,
        kind: input.kind,
        title: input.title,
        body: input.body,
        href: input.href,
        actorId: input.actorId,
        readAt: null,
        channels: JSON.stringify(input.channels),
        createdAt: stamp,
        updatedAt: stamp,
