import type { Actor, Role } from "@/types/member";
import { ROLE_RANK } from "@/types/member";
import type {
  PermissionAction,
  PermissionDecision,
  PermissionResource,
} from "@/types/permission";

/**
 * The single authorization entry point for Taskflow.
 *
 * Every Server Action, service method, Route Handler and permission-sensitive
 * UI component funnels through `can()`. Nothing else may branch on
 * `actor.role` directly — if you find yourself writing `role === "admin"`,
 * add an action to `PermissionAction` and a row to `ROLE_MATRIX` instead.
 *
 * Decision order:
 *   1. cross-tenant guard (`actor.orgId` must equal `resource.orgId`)
 *   2. platform staff bypass
 *   3. role matrix lookup
 *   4. ownership escalations (authors edit their own issues/comments)
 */

/** Minimum role required for each action, before ownership escalations. */
export const ROLE_MATRIX: Readonly<Record<PermissionAction, Role>> = {
  "org:read": "viewer",
  "org:update": "admin",
  "org:delete": "owner",
  "org:manage_billing": "owner",
  "org:manage_flags": "admin",
  "member:read": "viewer",
  "member:invite": "admin",
  "member:update_role": "admin",
  "member:remove": "admin",
  "project:create": "member",
  "project:read": "viewer",
  "project:update": "member",
  "project:archive": "admin",
  "project:delete": "owner",
  "issue:create": "member",
  "issue:read": "viewer",
  "issue:update": "member",
  "issue:assign": "member",
  "issue:archive": "member",
  "issue:delete": "admin",
  "comment:create": "member",
  "comment:read": "viewer",
  "comment:update": "member",
  "comment:delete": "admin",
  "activity:read": "member",
  "activity:export": "admin",
  "notification:read": "viewer",
  "notification:manage": "viewer",
  "webhook:manage": "admin",
};

/** Actions an actor may perform on their own content regardless of role rank. */
const OWNERSHIP_ESCALATIONS: Readonly<Partial<Record<PermissionAction, true>>> = {
  "issue:update": true,
  "issue:archive": true,
  "comment:update": true,
  "comment:delete": true,
  "notification:manage": true,
};

function isOwnedByActor(
  actor: Actor,
  resource: PermissionResource,
): boolean {
  switch (resource.kind) {
    case "issue":
      return (
        resource.authorId === actor.userId ||
        resource.assigneeId === actor.userId
      );
    case "comment":
      return resource.authorId === actor.userId;
    case "project":
      return resource.leadId === actor.userId;
    case "notification":
      return resource.recipientId === actor.userId;
    case "member":
      return resource.targetUserId === actor.userId;
    default:
      return false;
  }
}

/**
 * Answers "may this actor perform this action on this resource?".
 *
 * @param actor    the authenticated principal, always scoped to one org
 * @param action   a member of the closed `PermissionAction` vocabulary
 * @param resource the object being acted on, discriminated on `kind`
 */
export function can(
  actor: Actor,
  action: PermissionAction,
  resource: PermissionResource,
): boolean {
  return explain(actor, action, resource).allowed;
}

/** Same decision as `can()`, but reports why — used by the settings UI. */
export function explain(
  actor: Actor,
  action: PermissionAction,
  resource: PermissionResource,
): PermissionDecision {
  const base = { action, resourceKind: resource.kind } as const;

  if (actor.orgId !== resource.orgId) {
    return { ...base, allowed: false, reason: "denied_cross_tenant" };
  }

  if (actor.isPlatformStaff === true) {
    return { ...base, allowed: true, reason: "granted_by_staff" };
  }

  const required = ROLE_MATRIX[action];
  if (required === undefined) {
    return { ...base, allowed: false, reason: "denied_unknown_action" };
  }

  if (ROLE_RANK[actor.role] >= ROLE_RANK[required]) {
    return { ...base, allowed: true, reason: "granted_by_role" };
  }

  if (OWNERSHIP_ESCALATIONS[action] === true && isOwnedByActor(actor, resource)) {
    return { ...base, allowed: true, reason: "granted_by_ownership" };
  }

  return { ...base, allowed: false, reason: "denied_by_role" };
}

/** Thrown by `assertCan()`; mapped to a `forbidden` `ActionResult` by callers. */
export class PermissionDeniedError extends Error {
  readonly code = "forbidden" as const;

  constructor(
    readonly action: PermissionAction,
    readonly decision: PermissionDecision,
  ) {
    super(`Permission denied: ${action} on ${decision.resourceKind}`);
    this.name = "PermissionDeniedError";
  }
}

/** Throwing variant of `can()` for service-layer guard clauses. */
export function assertCan(
  actor: Actor,
  action: PermissionAction,
  resource: PermissionResource,
): void {
  const decision = explain(actor, action, resource);
  if (!decision.allowed) {
    throw new PermissionDeniedError(action, decision);
  }
}

/** Bulk evaluation used by navigation and toolbar components. */
export function canAll(
  actor: Actor,
  actions: readonly PermissionAction[],
  resource: PermissionResource,
): boolean {
  return actions.every((action) => can(actor, action, resource));
}
/**
 * Private helpers shared by the service layer.
 *
 * Two jobs only: build the `PermissionResource` descriptors `can()` expects
 * from a loaded row, and stamp the `EventEnvelope` every domain event carries.
 * Neither re-implements a cross-cutting concern — they are adapters onto
 * `@/lib/permissions` and `@/lib/event-bus`.
 */
import { toIsoTimestamp } from "@/types/common";
import type { Comment } from "@/types/comment";
import type { OrgId, UserId } from "@/types/common";
import type { EventEnvelope } from "@/types/event";
import type { Issue } from "@/types/issue";
import type { Actor, Member } from "@/types/member";
import type { PermissionResource } from "@/types/permission";
import type { Project } from "@/types/project";
import type { WebhookId } from "@/types/common";

/** Raised when a scoped lookup finds nothing; mapped to `not_found` by callers. */
export class NotFoundError extends Error {
  readonly code = "not_found" as const;

  constructor(
    readonly entity: string,
    readonly id: string,
  ) {
    super(`${entity} ${id} was not found`);
    this.name = "NotFoundError";
  }
}

/** Unwraps a repository read, turning the `null` case into a domain error. */
export function requireFound<T>(
  value: T | null | undefined,
  entity: string,
  id: string,
): T {
  if (value === null || value === undefined) {
    throw new NotFoundError(entity, id);
  }
  return value;
}

export function orgResource(orgId: OrgId): PermissionResource {
  return { kind: "organization", orgId };
}

export function billingResource(orgId: OrgId): PermissionResource {
  return { kind: "billing", orgId };
}

export function activityResource(orgId: OrgId): PermissionResource {
  return { kind: "activity", orgId };
}

export function notificationResource(
  orgId: OrgId,
  recipientId: UserId,
): PermissionResource {
  return { kind: "notification", orgId, recipientId };
}

export function webhookResource(
  orgId: OrgId,
  webhookId: WebhookId | null,
): PermissionResource {
  return { kind: "webhook", orgId, webhookId };
}

export function memberResource(member: Member): PermissionResource {
  return {
    kind: "member",
    orgId: member.orgId,
    memberId: member.id,
    targetUserId: member.userId,
    targetRole: member.role,
  };
}

export function projectResource(project: Project): PermissionResource {
  return {
    kind: "project",
    orgId: project.orgId,
    projectId: project.id,
    visibility: project.visibility,
    leadId: project.leadId,
  };
}

export function issueResource(issue: Issue): PermissionResource {
  return {
    kind: "issue",
    orgId: issue.orgId,
    projectId: issue.projectId,
    issueId: issue.id,
    authorId: issue.authorId,
    assigneeId: issue.assigneeId,
  };
}

export function commentResource(comment: Comment): PermissionResource {
  return {
    kind: "comment",
    orgId: comment.orgId,
    commentId: comment.id,
    authorId: comment.authorId,
  };
}

/** The three fields the bus stamps on every payload. */
export function envelope(orgId: OrgId, actorId: UserId | null): EventEnvelope {
  return { orgId, actorId, occurredAt: toIsoTimestamp(new Date()) };
}

/** Same envelope, taken from an `Actor` rather than assembled by hand. */
export function actorEnvelope(actor: Actor): EventEnvelope {
  return envelope(actor.orgId, actor.userId);
}

/** Names the fields an update actually changed, for `issue.updated`. */
export function changedFields<T extends object>(
  before: T,
  after: T,
): readonly string[] {
  return Object.keys(after).filter(
    (key) =>
      JSON.stringify(before[key as keyof T]) !==
      JSON.stringify(after[key as keyof T]),
  );
}
/**
 * Private paging helpers shared by the repositories in this directory.
 *
 * Not part of the public data-access surface — repositories re-export nothing
 * from here. Keyset (cursor) pagination is expressed as a row-value comparison
 * so a page boundary is stable even when two rows share a `created_at`.
 */
import { sql } from "drizzle-orm";
import { decodeCursor, encodeCursor } from "./base-repository";
import { makePage } from "@/types/common";
import type { Page } from "@/types/common";
import type { SQL } from "drizzle-orm";
import type { SQLiteColumn } from "drizzle-orm/sqlite-core";

export interface KeysetSort {
  readonly sortColumn: SQLiteColumn;
  readonly idColumn: SQLiteColumn;
}

/**
 * Predicate that resumes a descending listing after `cursor`. Returns
 * `undefined` for a first page or an unparseable cursor — a bad cursor
 * degrades to "start from the top", never to an error page.
 */
export function keysetPredicate(
  sort: KeysetSort,
  cursor: string | null | undefined,
): SQL | undefined {
  if (!cursor) return undefined;
  const decoded = decodeCursor(cursor);
  if (!decoded) return undefined;

  return sql`(${sort.sortColumn}, ${sort.idColumn}) < (${decoded.sortValue}, ${decoded.id})`;
}

/** SQLite tolerates a `LIMIT` of `n + 1`; that extra row is the has-more probe. */
export function probeLimit(limit: number): number {
  return Math.max(1, Math.min(limit, 100)) + 1;
}

/**
 * Turns an over-fetched row array into a `Page`, dropping the probe row and
 * deriving the next cursor from the last row that survived.
 */
export function toPage<TRow, TOut>(
  rows: readonly TRow[],
  limit: number,
  total: number,
  map: (row: TRow) => TOut,
  cursorOf: (row: TRow) => { id: string; sortValue: string },
): Page<TOut> {
  const capped = Math.max(1, Math.min(limit, 100));
  const hasMore = rows.length > capped;
  const visible = hasMore ? rows.slice(0, capped) : rows;
  const last = visible.at(-1);

  const nextCursor =
    hasMore && last
      ? encodeCursor(cursorOf(last).id, cursorOf(last).sortValue)
      : null;

  return makePage(visible.map(map), nextCursor, total);
}

/** Drops the `undefined` slots so `and(...)` never sees a hole. */
export function compact(
  ...predicates: readonly (SQL | undefined)[]
): readonly SQL[] {
  return predicates.filter((value): value is SQL => value !== undefined);
}
/**
 * Builds the daily digest bundle per recipient from unread notifications inside the org's digest window.
 *
 * Must call (do not reimplement): isEnabled, renderEmail
 */
import { isEnabled } from "@/lib/feature-flags";
import { DIGEST_MAX_ENTRIES } from "@/config/constants";
import * as notificationRepo from "@/server/repositories/notification-repository";
import * as preferenceRepo from "@/server/repositories/notification-preference-repository";
import * as orgRepo from "@/server/repositories/organization-repository";
import { renderEmail } from "./email-service";
import { buildFlagContext } from "./feature-flag-service";
import type { RenderedEmail } from "@/server/services/email-service";
import type { IsoTimestamp, OrgId, UserId } from "@/types/common";
import type { User } from "@/types/member";
import type { DigestBundle, DigestEntry } from "@/types/notification";

/** A digest with fewer entries than this is not worth an email. */
const MIN_ENTRIES = 1;

/**
 * Collects one recipient's unread notifications inside the window. Returns
 * `null` — rather than an empty bundle — when the org's plan does not include
 * the digest, or when there is nothing to say: the caller treats `null` as
 * "send nothing", so a quiet day produces no mail at all.
 */
export async function buildDigest(
  orgId: OrgId,
  recipientId: UserId,
  windowStart: IsoTimestamp,
  windowEnd: IsoTimestamp,
): Promise<DigestBundle | null> {
  const org = await orgRepo.findOrgById(orgId);
  if (!org) return null;

  if (!isEnabled("digest_email", buildFlagContext(null, org))) return null;

  const unread = await notificationRepo.listUnreadSince(
    orgId,
    recipientId,
    windowStart,
  );

  const entries: DigestEntry[] = unread
    .filter((notification) => notification.createdAt <= windowEnd)
    .map((notification) => ({
      notificationId: notification.id,
      kind: notification.kind,
      title: notification.title,
      href: notification.href,
      occurredAt: notification.createdAt,
    }))
    .slice(0, DIGEST_MAX_ENTRIES);

  if (entries.length < MIN_ENTRIES) return null;

  return { orgId, recipientId, entries, windowStart, windowEnd };
}

/**
 * Who gets a digest: everyone who set at least one notification kind to
 * `digestOnly`. Opting into the digest is what suppresses the immediate
 * emails, so the two lists are two views of the same preference.
 */
export async function listDigestRecipients(
  orgId: OrgId,
): Promise<readonly UserId[]> {
  return preferenceRepo.listDigestSubscribers(orgId);
}

/** Renders one bundle through the shared email pipeline. */
export async function renderDigest(
  bundle: DigestBundle,
  recipient: User,
): Promise<RenderedEmail> {
  return renderEmail("digest", {
    orgId: bundle.orgId,
    recipientName: recipient.name,
    entryCount: bundle.entries.length,
    windowStart: bundle.windowStart,
    windowEnd: bundle.windowEnd,
    headline: bundle.entries[0]?.title ?? "",
  });
}
/**
 * Recomputes the usage counters that every `LimitCheck` compares against.
 *
 * Must call (do not reimplement): assertOrgScope, subscribe, getPlanLimits
 */
import { getPlanLimits } from "@/config/plan-limits";
import { emit, subscribe } from "@/lib/event-bus";
import { assertOrgScope } from "@/lib/tenant";
import * as orgRepo from "@/server/repositories/organization-repository";
import * as usageRepo from "@/server/repositories/usage-repository";
import { toIsoTimestamp } from "@/types/common";
import type { OrgId } from "@/types/common";
import type { Unsubscribe } from "@/types/event";
import type { Actor } from "@/types/member";
import type { OrganizationUsage } from "@/types/organization";

/** Fraction of a quota at which the "approaching limit" event fires. */
const WARN_THRESHOLD = 0.9;

export async function getUsage(
  actor: Actor,
  orgId: OrgId,
): Promise<OrganizationUsage> {
  assertOrgScope(actor, orgId);
  return usageRepo.getUsage(orgId);
}

/**
 * Full recount from the source tables. Called by the rollup job and by every
 * event that could have moved a counter — after recounting, the seat and
 * project totals are checked against the plan so a breach surfaces as an
 * event rather than waiting for the next write to be rejected.
 */
export async function recomputeUsage(
  orgId: OrgId,
): Promise<OrganizationUsage> {
  const usage = await usageRepo.recomputeUsage(orgId);
  const org = await orgRepo.findOrgById(orgId);
  if (!org) return usage;

  const limits = getPlanLimits(org.plan);

  if (usage.seatsUsed >= limits.seats * WARN_THRESHOLD) {
    await emit("billing.limit_exceeded", {
      orgId,
      actorId: null,
      occurredAt: toIsoTimestamp(new Date()),
      resource: "seats",
      limit: limits.seats,
      used: usage.seatsUsed,
    });
  }

  if (usage.projectsUsed >= limits.projects * WARN_THRESHOLD) {
    await emit("billing.limit_exceeded", {
      orgId,
      actorId: null,
      occurredAt: toIsoTimestamp(new Date()),
      resource: "projects",
      limit: limits.projects,
      used: usage.projectsUsed,
    });
  }

  return usage;
}

/**
 * Every event that changes a counted resource nudges the cache. The deltas are
 * cheap; the periodic rollup is what corrects any drift they accumulate.
 */
export function registerUsageListeners(): Unsubscribe {
  const offs: Unsubscribe[] = [
    subscribe("issue.created", async (payload) => {
      await usageRepo.incrementUsage(payload.orgId, { issuesUsed: 1 });
    }),
    subscribe("issue.archived", async (payload) => {
      await usageRepo.incrementUsage(payload.orgId, { issuesUsed: -1 });
    }),
    subscribe("project.created", async (payload) => {
      await usageRepo.incrementUsage(payload.orgId, { projectsUsed: 1 });
    }),
    subscribe("project.archived", async (payload) => {
      await usageRepo.incrementUsage(payload.orgId, {
        projectsUsed: -1,
        issuesUsed: -payload.issuesArchived,
      });
    }),
    subscribe("member.joined", async (payload) => {
      await usageRepo.incrementUsage(payload.orgId, { seatsUsed: 1 });
    }),
    subscribe("member.removed", async (payload) => {
      await usageRepo.incrementUsage(payload.orgId, { seatsUsed: -1 });
    }),
  ];

  return () => {
    for (const off of offs) off();
  };
}
